// The Worker entry: OpenNext's handler with one fix on the way out.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- the file only exists after a build
// @ts-ignore -- generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

/**
 * OpenNext labels cached pages for a CDN in front of the app (written for
 * AWS CloudFront): `s-maxage=…, stale-while-revalidate=2592000`. Cloudflare
 * doesn't cache a Worker's responses, so that does nothing at the edge — but
 * Chrome honours stale-while-revalidate for fetches, and kept serving the
 * page data (RSC) of client-side navigations from its own cache for up to 30
 * days. After a deploy that old data points at scripts the deploy removed, so
 * navigating showed "Something went wrong" until a full reload.
 *
 * Browsers now revalidate every page and its data (an ETag check, a 304 when
 * nothing changed). Responses that set their own browser lifetime (max-age)
 * are left alone.
 */
function forBrowsers(response: Response): Response {
  const cacheControl = response.headers.get("cache-control");
  if (!cacheControl || !/s-maxage/i.test(cacheControl) || /(?:^|[\s,])max-age=/i.test(cacheControl))
    return response;
  const fixed = new Response(response.body, response);
  fixed.headers.set("cache-control", "public, max-age=0, must-revalidate");
  return fixed;
}

export default {
  async fetch(request, env, ctx) {
    return forBrowsers(await handler.fetch(request, env, ctx));
  },
} satisfies ExportedHandler<CloudflareEnv>;

// The Durable Object behind ISR revalidation (wrangler.jsonc binds it).
